    if (typeof data === 'string' && data.startsWith('42["chat.')) {
      try { const j = JSON.parse(data.slice(2)), corps = j[1] || {}; const cleTxt = Object.keys(corps).find((k) => typeof corps[k] === 'string' && /text|message|content|msg|body/i.test(k));
        if (cleTxt && typeof j[0] === 'string' && (!B.tchatFmt || B.tchatFmt.ev !== j[0] || JSON.stringify(Object.keys(B.tchatFmt.ex)) !== JSON.stringify(Object.keys(corps)))) { const ex = Object.assign({}, corps); ex[cleTxt] = ''; B.tchatFmt = { ev: j[0], txt: cleTxt, ex }; sauveB(); note('Tchat : forme des messages apprise (' + j[0] + ') — vos réponses Telegram pourront partir même si la case du tchat est introuvable'); }
      } catch (e) {}
    }
    // Une technique lancée à la main avec plus que « cible » (case d'arrivée…) : j'apprends le nom exact du champ attendu par le jeu.
