      if (!t || c.interdits.has(id) || S.cd[id] > 0 || !(t.effects || []).some((x) => x.kind === genre)) continue;
      if (genre === 'summon' && (t.effects || []).some((x) => x.kind === 'summon' && (x.powerPercent != null || x.hpPercent != null))) continue; // marionnette de combat : gérée à part, jamais posée comme simple leurre
      if (moi.ap < (t.apCost || 0) || moi.chakra < (t.chakraCost || 0) || ((moi.cooldowns || {})[id] > 0) || ((moi.castsThisTurn || {})[id] || 0) >= (t.castsPerTurn || 99)) continue;
