      c.ents.forEach((o) => { if (o.alive !== false && o.id !== moi.id && o.id !== e.id) pris.add(o.x + ',' + o.y); });
      if (atteignables(c, moi, e, pr.pm, pris).some((q) => { const d = man(q, cell); return d >= 1 && d <= pr.portee && (pr.portee <= 1 || vueCombat(c, moi, q, cell, pris)); })) total += attire ? pr.poids * 0.4 : pr.poids;
