    const equipe = [...c.ents.values()].filter((a) => a.alive !== false && a.team === moi.team && (a.id === c.moi || estJoueur(a)));
    const boss = e.hp > 5 * (moi.maxHp || moi.hp || 1) && equipe.length > 1; // boss en groupe : sa vraie portée m'est mal connue, je ne le rapproche de personne
    const victime = equipe.find((a) => (man(q, a) <= R && man(e, a) > R) || (boss && man(q, a) < man(e, a)));
