      const important = avecSuivi || ennemis.some((e) => (e.maxHp || e.hp || 0) >= 15000) || duree > 240;
      if (!important) return;
      const tri = (o) => Object.keys(o).sort((a, b) => o[b] - o[a]);
      const totDeg = Object.values(R.deg).reduce((a, b) => a + b, 0) || 1;
      const nomJ = (pid) => { const e = [...c.ents.values()].find((x) => x.id === 'p:' + pid || x.playerId === pid); return e ? e.name : String(pid).slice(0, 8); };
      const lignes = [];
      lignes.push(new Date().toLocaleTimeString().slice(0, 5) + ' · contre ' + [...new Set(ennemis.map((e) => (e.name || e.mobId) + (e.level ? ' niv.' + e.level : '')))].join(', ') + ' · ' + Math.round(duree) + ' s · ' + R.tour + ' tours · ' + (d.winnerTeam === moiT ? 'VICTOIRE' : 'défaite'));
      lignes.push('DÉGÂTS INFLIGÉS : ' + tri(R.deg).map((k) => k + ' ' + R.deg[k] + ' (' + Math.round(100 * R.deg[k] / totDeg) + ' %)').join(' | '));
      if (Object.keys(R.soin).length) lignes.push('SOINS : ' + tri(R.soin).map((k) => k + ' ' + R.soin[k]).join(' | '));
      lignes.push('DÉGÂTS REÇUS : ' + tri(R.recu).map((k) => k + ' ' + R.recu[k]).join(' | '));
      lignes.push('SORTS ENNEMIS (coups · total · plus gros · cibles) : ' + Object.keys(R.sortE).sort((a, b) => R.sortE[b].tot - R.sortE[a].tot).map((k) => { const o = R.sortE[k]; return k.split('.').pop() + ' ' + o.n + ' coups · ' + o.tot + ' · max ' + o.max + ' · ' + Object.keys(o.cibles).map((x) => x + '×' + o.cibles[x]).join('/'); }).join(' | '));
      lignes.push('SORTS DE CHACUN : ' + tri(R.sorts).slice(0, 60).map((k) => k + ' ×' + R.sorts[k]).join(' | '));
      if (Array.isArray(d.rewards)) lignes.push('RÉCOMPENSES : ' + d.rewards.filter((r) => { const e = [...c.ents.values()].find((x) => x.id === 'p:' + r.playerId || x.playerId === r.playerId); return !e || garde(e.id); }).map((r) => nomJ(r.playerId) + ' ' + (r.xp || 0) + ' XP' + ((r.items || []).length ? ' [' + r.items.map((i) => i.itemId + (i.quantity > 1 ? '×' + i.quantity : '')).join(', ') + ']' : '')).join(' | '));
      joueurs.filter((e) => garde(e.id)).forEach((e) => { const o = Object.assign({}, e); delete o.x; delete o.y; delete o.path; if (e.id === c.moi) { delete o.skills; delete o.cooldowns; delete o.castsThisTurn; } lignes.push('FICHE ' + (e.name || e.id) + ' : ' + JSON.stringify(o).slice(0, c.rapTous ? 2500 : 900)); });
      ennemis.forEach((e) => { const o = Object.assign({}, e); delete o.x; delete o.y; delete o.path; lignes.push('FICHE ENNEMI ' + (e.name || e.id) + ' : ' + JSON.stringify(o).slice(0, 700)); });
      if (R.ps) lignes.push('PAR JOUEUR ET PAR SORT (dégâts · soins · coups · plus gros) :\n' + Object.keys(R.ps).sort((a, b) => (R.ps[b].d + R.ps[b].h) - (R.ps[a].d + R.ps[a].h)).slice(0, 80).map((k) => { const o = R.ps[k]; return '  ' + k + ' : ' + o.d + ' dég. · ' + o.h + ' soins · ' + o.n + ' coups · max ' + o.max; }).join('\n'));
