      const tire = (q) => ennemis.some((e) => { const d = man(q, e); return d >= (principal.min || 1) && d <= principal.max && (!principal.los || d <= 1 || vueDe(q, e)); }); // même règle que pour tirer : aligné, rien sur la ligne
      const loin = (q) => Math.min(...ennemis.map((e) => man(q, e)));
