      const ici = { x: moi.x, y: moi.y, d: 0 };
      const cibleF = ennemis.find((e) => e.id === c.focus);
      const voitF = (q) => { if (!cibleF) return false; const d = man(q, cibleF); return d >= (principal.min || 1) && d <= principal.max && (!principal.los || d <= 1 || vueDe(q, cibleF)); };
      if (cibleF && tire(ici) && !voitF(ici)) { // je peux tirer d'ici, mais pas sur ma cible : un ou deux pas suffisent-ils à la retrouver ?
        const cf = mesCases(c, moi).filter((q) => q.d > 0 && q.d <= Math.min(2, moi.mp) && voitF(q)).map((q) => ({ x: q.x, y: q.y, d: q.d, m: menace(c, moi, q, ennemis) }));
        if (cf.length) { const mf = cf.reduce((a, b) => (b.d < a.d || (b.d === a.d && b.m < a.m) ? b : a)); if (!c.ditVoitF) { c.ditVoitF = true; note('Tactique : ' + mf.d + ' pas pour garder ma cible en ligne de tir plutôt que d’en changer'); } return { type: 'move', to: { x: mf.x, y: mf.y }, tactique: true }; }
      }
