          if (c2.length) { const m2 = c2.reduce((a, b) => (b.m < a.m || (b.m === a.m && b.d < a.d) ? b : a)); if (!c.ditPas) { c.ditPas = true; note('Tactique : ligne de tir bouchée, je me décale pour tirer'); } return { type: 'move', to: { x: m2.x, y: m2.y }, tactique: true }; }
