    // Sort en ligne : il frappe chaque ennemi entre moi et la case visée (même rangée ou même colonne).
    const surLigne = (cible) => ennemis.filter((x) => (x.x === moi.x && cible.x === moi.x && Math.sign(x.y - moi.y) === Math.sign(cible.y - moi.y) && Math.abs(x.y - moi.y) <= Math.abs(cible.y - moi.y)) || (x.y === moi.y && cible.y === moi.y && Math.sign(x.x - moi.x) === Math.sign(cible.x - moi.x) && Math.abs(x.x - moi.x) <= Math.abs(cible.x - moi.x))).length;
