        for (let dx = -r; dx <= r; dx++) for (let dy = -r; dy <= r; dy++) { const q = { x: e.x + dx, y: e.y + dy }, dq = man(moi, q); if (dq < (x.min || 0) || dq > (x.max || 0)) continue; if (t.targetType === 'ally' && (dx || dy)) continue; if (t.lineOfSight && dq > 1 && !vueDe(moi, q)) continue; if ([...c.ents.values()].some((o) => o.alive !== false && o.team !== moi.team && o.x === q.x && o.y === q.y)) continue; if (!best || dq < best.d) best = { x: q.x, y: q.y, d: dq }; }
