      const coutPV = (x) => { const f = (S.techniques.get(x.id) || {}).effects || []; return f.reduce((a2, y) => a2 + (y.casterHpCost || 0), 0) / 100 * pvM; }; // Renaissance, Transfusion : me coûtent des PV
      const cands = equipe.filter(bas).sort((a, b) => part(a) - part(b));
