  function lanceBrisage() { S.nivA = 0; S.brisDebut = Date.now(); S.nbBrisRun = 0; S.brisFini = 0; if (CFG.mode !== 'brisage') CFG.modeAvant = CFG.mode; CFG.mode = 'brisage'; S.brisKO = 0; S.brisEchecs = 0; S.retraitBrisKO = {}; S.brisCoffreDit = false; sauve(); S.cibleId = null; note(Number(CFG.brisInutile) === 1 ? 'Mode Brisage : je brise tout l’équipement inutile à Ciel (sac et coffre), sans lancer de combat' : 'Mode Brisage : je brise tout l’équipement sous le niveau ' + (Number(CFG.brisNiv) || '?') + ' (sac puis coffre), sans lancer de combat'); affiche(); }
  // Drarito — pièce sûre à briser ou à vendre : équipement déjà essayé et moins bon que le mien, de couleur CONNUE grise ou verte.
