    if ((!seuil && !estDrarito()) || S.combat || !B.brisFmt || S.brisKO > Date.now() || !S.invOk) return false;
    if (estDrarito() && CFG.mode !== 'brisage' && S.inv.filter((x) => x && x.itemId).length < (S.invCap || 60) - 10) return false; // Drarito — brisage automatique seulement quand le sac est presque plein (ou sur demande)
