      const sortis = S.inv.filter((y) => y && y.itemId).length - avant;
      if (sortis <= 0) { paquet.forEach((x) => { (S.retraitBrisKO = S.retraitBrisKO || {})[x.itemId + ':' + x.roll] = 1; }); note('Brisage : le coffre n’a rien rendu (' + paquet.length + ' demandés) — je laisse ces pièces'); }
