    if (!sac.length && !cof.length) { if (CFG.mode === 'brisage' && !S.brisFini) { S.brisFini = 1; note('Brisage terminé : plus rien d’inutile (' + (S.nbBrisRun || 0) + ' pièces brisées)'); CFG.mode = CFG.modeAvant || 'xp'; sauve(); } return false; }
    const lotS = sac.slice(0, unParUn ? 1 : 60), lotC = unParUn && lotS.length ? [] : cof.slice(0, (unParUn ? 1 : 60) - lotS.length);
    const corps = { pieces: lotS.map((x) => ({ index: x.index, itemId: x.itemId, roll: x.roll })), vault: lotC.map((x) => ({ itemId: x.itemId, roll: x.roll, quantity: 1 })) };
