    S.brisEchecs = 0; S.nbBris = (S.nbBris || 0) + tous.length; S.nbBrisRun = (S.nbBrisRun || 0) + tous.length;
    const noms = {}; tous.forEach((x) => { noms[x.itemId] = (noms[x.itemId] || 0) + 1; });
    note('🔨 Brisé ' + tous.length + ' pièce(s) inutiles (' + lotS.length + ' du sac, ' + lotC.length + ' du coffre) : ' + Object.keys(noms).map((k) => k + (noms[k] > 1 ? '×' + noms[k] : '')).join(', ').slice(0, 300));
