      const c = connus.find((x) => simple(x.name).indexOf(simple(arg)) >= 0 || simple(x.zoneName).indexOf(simple(arg)) >= 0);
      if (!c) return tgDit('Aucun sceau connu ne correspond à « ' + arg + ' ». Envoyez /tp pour la liste.');
      if (S.combat || !enMonde()) return tgDit('Impossible maintenant (en combat ou à l’intérieur).');
      stop(); envoie('teleport.remote', { destinationId: c.id }); S.tpA = Date.now() + 60000; NAV.route = []; NAV.but = null; NAV.prog = null;
